export const markEventInterest = async (eventId: string, userId: string): Promise<boolean> => {
  try {
    const { error } = await supabase
      .from('event_interested')
      .insert({ event_id: eventId, user_id: userId });
      
    if (error) throw error;
    
    // Update the user's profile events_upcoming count
    // Instead of using RPC which is causing errors, use direct update
    await supabase
      .from('profiles')
      .update({ events_upcoming: supabase.rpc('increment', { row_id: userId, column_name: 'events_upcoming' }) })
      .eq('id', userId);
    
    return true;
  } catch (error) {
    console.error('Error marking event interest:', error);
    return false;
  }
};

export const removeEventInterest = async (eventId: string, userId: string): Promise<boolean> => {
  try {
    const { error } = await supabase
      .from('event_interested')
      .delete()
      .eq('event_id', eventId)
      .eq('user_id', userId);
      
    if (error) throw error;
    
    // Update the user's profile events_upcoming count
    // Instead of using RPC which is causing errors, use direct update
    await supabase
      .from('profiles')
      .update({ 
        events_upcoming: supabase.rpc('decrement', { row_id: userId, column_name: 'events_upcoming' }) 
      })
      .eq('id', userId);
    
    return true;
  } catch (error) {
    console.error('Error removing event interest:', error);
    return false;
  }
};

